"""Project source-count work from executed pilots; does not launch production."""
import csv,glob,json,statistics,pathlib,datetime,collections
root=pathlib.Path('.')
def read(p): return list(csv.DictReader(open(p)))
rows=[]
# Pilot times include compile/adaptation. Linear scaling is deliberately labelled rough.
for p in sorted(root.glob('outputs/pilot-c[25]*-r0-run.csv')):
 r=read(p)[0]; ch=int(r['ch']); target=21000 if ch==2 else 80000; reps=100 if ch==2 else 250
 observed=sum(int(r[k])for k in ['nadapt','nburn','ndraw'])
 seconds=float(r['elapsed_seconds'])
 rows.append(dict(chapter=ch,condition=p.name.removesuffix('-run.csv'),observed_iterations=observed,observed_elapsed_seconds=seconds,source_iterations_per_dataset=target,source_datasets=reps,rough_single_worker_hours=seconds/observed*target*reps/3600,basis='Linear total-pilot scaling including compilation; not steady-state benchmark, convergence guarantee, or hard compute denial'))
trials=read('outputs/trial-records.csv'); times={tuple(r[k]for k in ['mechanism','q','missing','seed','method']):float(r['elapsed_seconds'])for r in trials}
checkpoints=[json.load(open(p))for p in glob.glob('outputs/pilot-c6-*-checkpoint.json')]
cp=sum(c['elapsed_seconds']for c in checkpoints if c['returncode']==0)
# Saved 20 datasets per condition are a baseline; continuation adds 980, never replaces them.
c6=dict(conditions=48,completed_datasets_per_condition=20,target_datasets_per_condition=1000,remaining_datasets=48*980,remaining_method_fits=48*980*2,observed_fit_elapsed_seconds=sum(times.values()),observed_process_elapsed_seconds=cp,remaining_fit_hours=sum(times.values())*49/3600,remaining_process_hours=cp*49/3600,ideal_four_worker_fit_hours=sum(times.values())*49/3600/4,ideal_four_worker_process_hours=cp*49/3600/4,scaling_caveat='Ideal division is not measured parallel speedup; startup, contention, failures, Hessian checks and changed configurations add cost.')
plan=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),hardware={'cpu_quota':open('/sys/fs/cgroup/cpu.max').read().strip(),'memory_limit_bytes':int(open('/sys/fs/cgroup/memory.max').read())},chapter2_rough_single_worker_days=sum(r['rough_single_worker_hours']for r in rows if r['chapter']==2)/24,chapter5_rough_single_worker_days=sum(r['rough_single_worker_hours']for r in rows if r['chapter']==5)/24,chapter5_steady_state_reference=json.load(open('outputs/resource-projection.json')),chapter6=c6,jags_conditions=rows,limits=['One-chain diagnostics do not establish convergence; source length is not a convergence guarantee.','Original-vs-reconstruction Rhat uses two model representations on shared generated data; add at least four independent chains and bulk/tail checks before inference.','Chapter2 full grid currently includes symmetric item arm as additional diagnostic; source-condition counts must be audited before dispatch.','BayesTwin smoke tests and original Appendix programs are not parameter recovery.','Never shrink whole-dissertation scope based on these costs. No months-long job launched.'],bounded_next_steps=[{'item':'Chapter6','action':'Validate isolated batch execution against twelve existing datasets, then time a bounded batch; preserve existing 20-replicate baseline. Use chunks with explicit manifests and fail-fast output checks.','decision':'Continue only after scientific-review corrections and independent covariance/SE checks; do not treat path-SE reconstruction as variance-SE reproduction.'},{'item':'Chapter2','action':'Run four source-length independent chains on the same floor dataset, compare bulk/tail diagnostics and original posterior before100-dataset continuation.','remaining':'Full power/recovery means and SDs across all conditions.'},{'item':'Chapter5','action':'Benchmark fixed-seed repeated timed sampling at representative N/J before engine changes; validate posterior and estimand for any reparameterization.','remaining':'All250 datasets per condition; short pilot draws excluded from scientific verdicts.'}])
pathlib.Path('outputs/production-resource-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
print(json.dumps({k:v for k,v in plan.items()if k not in ['jags_conditions','limits','bounded_next_steps']},indent=2))
